      "file": "OrderService.java",
      "body": "import java.time.Clock;\nimport java.time.Instant;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport java.util.concurrent.atomic.AtomicLong;\n\npublic class OrderService {\n    private final CartService carts;\n    private final RiderPool riders;\n    private final Clock clock;\n    private final AtomicLong orderIds = new AtomicLong();\n    private final Map<String, Order> orders = new ConcurrentHashMap<>();\n\n    public OrderService(CartService carts, RiderPool riders, Clock clock) {\n        this.carts = carts;\n        this.riders = riders;\n        this.clock = clock;\n    }\n\n    /** Idempotent: calling it twice for the same cart returns the same order. */\n    public Order placeOrder(String cartId) {\n        Cart cart = carts.cart(cartId);\n        synchronized (cart) {\n            if (cart.order() != null) return cart.order();\n            List<Hold> holds = cart.allHolds();\n            if (holds.isEmpty()) throw new CheckoutException(\"cart is empty\");\n\n            Instant now = clock.instant();\n            DarkStore store = cart.store();\n            List<Hold> committed = new ArrayList<>();\n            for (Hold hold : holds) {\n                if (!store.commit(hold, now)) {\n                    // All-or-nothing: put back what we already took and free the rest.\n                    committed.forEach(c -> store.restock(c.sku(), c.qty()));\n                    holds.stream().filter(h -> !committed.contains(h)).forEach(store::release);\n                    cart.clearHolds();\n                    throw new CheckoutException(\"hold on \" + hold.sku() + \" expired, please add it again\");\n                }\n                committed.add(hold);\n            }\n\n            Order order = new Order(\"O-\" + orderIds.incrementAndGet(), store, cart.deliverTo(), cart.quantities());\n            orders.put(order.id(), order);\n            cart.setOrder(order);\n            return order;\n        }\n    }\n\n    public boolean startPacking(Order order) {\n        return step(order, OrderStatus.PLACED);\n    }\n\n    public boolean finishPacking(Order order) {\n        return step(order, OrderStatus.PACKING);\n    }\n\n    /** PACKED -> OUT_FOR_DELIVERY. Claims a rider atomically; false if none is free. */\n    public boolean dispatch(Order order) {\n        synchronized (order) {\n            if (order.status() != OrderStatus.PACKED) return false;\n            return riders.claimFor(order.store().location()).map(rider -> {\n                order.assignRider(rider);\n                order.transitionTo(OrderStatus.OUT_FOR_DELIVERY);\n                return true;\n            }).orElse(false);\n        }\n    }\n\n    public boolean deliver(Order order) {\n        synchronized (order) {\n            if (order.status() != OrderStatus.OUT_FOR_DELIVERY) return false;\n            order.transitionTo(OrderStatus.DELIVERED);\n            order.rider().release();\n            return true;\n        }\n    }\n\n    /** Only the thread whose transition succeeds restocks, so stock is never returned twice. */\n    public boolean cancel(Order order) {\n        synchronized (order) {\n            if (!order.status().canCancel()) return false;\n            order.transitionTo(OrderStatus.CANCELLED);\n            order.store().restockAll(order.items());\n            return true;\n        }\n    }\n\n    private boolean step(Order order, OrderStatus expected) {\n        synchronized (order) {\n            if (order.status() != expected) return false;\n            order.transitionTo(expected.next());\n            return true;\n        }\n    }\n}"
