    "body": "import java.time.Duration;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.concurrent.ConcurrentHashMap;\nimport java.util.concurrent.atomic.AtomicInteger;\nimport java.util.concurrent.atomic.AtomicReference;\n\npublic class Main {\n    public static void main(String[] args) {\n        MutableClock clock = new MutableClock(Instant.parse(\"2026-01-01T10:00:00Z\"));\n\n        DarkStore koramangala = new DarkStore(\"Koramangala\", new Location(12.9352, 77.6245));\n        DarkStore indiranagar = new DarkStore(\"Indiranagar\", new Location(12.9784, 77.6408));\n        koramangala.addStock(\"milk\", 1);      // the last unit\n        koramangala.addStock(\"bread\", 20);\n        indiranagar.addStock(\"milk\", 30);\n\n        StoreSelector selector = new NearestStoreSelector(List.of(koramangala, indiranagar), 5.0);\n        CartService carts = new CartService(selector, clock, Duration.ofMinutes(10));\n\n        RiderPool riders = new RiderPool(new NearestRiderStrategy());\n        riders.add(new Rider(\"R1\", new Location(12.9340, 77.6250)));\n        riders.add(new Rider(\"R2\", new Location(12.9500, 77.6300)));\n        riders.add(new Rider(\"R3\", new Location(12.9900, 77.6000)));\n        OrderService orders = new OrderService(carts, riders, clock);\n\n        // 1. Nearest dark store ------------------------------------------------\n        System.out.println(\"== 1. Nearest dark store ==\");\n        Location home = new Location(12.9300, 77.6200);\n        DarkStore chosen = selector.select(home).orElseThrow();\n        System.out.printf(\"Customer at (%.4f, %.4f) -> %s (%.1f km)%n\",\n                home.lat(), home.lon(), chosen.name(), chosen.location().distanceKm(home));\n        Location faraway = new Location(13.2000, 77.9000);\n        System.out.println(\"Customer 40+ km away -> \" + selector.select(faraway).map(DarkStore::name).orElse(\"no store serves this location\"));\n\n        // 2. Last unit: 20 buyers race for 1 milk --------------------------------\n        System.out.println();\n        System.out.println(\"== 2. Last unit of milk, 20 buyers at the same instant ==\");\n        for (int i = 0; i < 20; i++) carts.createCart(\"buyer-\" + i, home);\n        AtomicInteger got = new AtomicInteger();\n        AtomicInteger soldOut = new AtomicInteger();\n        AtomicReference<String> winner = new AtomicReference<>();\n        ConcurrentRunner.runAll(20, i -> {\n            AddResult r = carts.addItem(\"buyer-\" + i, \"milk\", 1);\n            if (r.added()) {\n                got.incrementAndGet();\n                winner.set(\"buyer-\" + i);\n            } else {\n                soldOut.incrementAndGet();\n            }\n        });\n        System.out.println(\"Added to cart: \" + got.get() + \", told 'sold out': \" + soldOut.get());\n        System.out.println(\"Milk available now: \" + koramangala.available(\"milk\", clock.instant()));\n\n        // 3. Hold expiry ---------------------------------------------------------\n        System.out.println();\n        System.out.println(\"== 3. The winner never pays: hold expires after 10 minutes ==\");\n        clock.advance(Duration.ofMinutes(11));\n        System.out.println(\"Milk available after 11 minutes: \" + koramangala.available(\"milk\", clock.instant()));\n        carts.createCart(\"late-buyer\", home);\n        System.out.println(\"Late buyer adds milk: \" + carts.addItem(\"late-buyer\", \"milk\", 1).message());\n        try {\n            orders.placeOrder(winner.get());\n        } catch (CheckoutException e) {\n            System.out.println(\"Original winner checks out: \" + e.getMessage());\n        }\n\n        // 4. Idempotent checkout -------------------------------------------------\n        System.out.println();\n        System.out.println(\"== 4. Double-click on 'Place order' (8 parallel requests) ==\");\n        Set<String> orderIds = ConcurrentHashMap.newKeySet();\n        ConcurrentRunner.runAll(8, i -> orderIds.add(orders.placeOrder(\"late-buyer\").id()));\n        System.out.println(\"Distinct orders created: \" + orderIds.size());\n        System.out.println(\"Milk on hand after checkout: \" + koramangala.onHand(\"milk\"));\n\n        // 5. Order lifecycle + live status ----------------------------------------\n        System.out.println();\n        System.out.println(\"== 5. Order lifecycle with live status ==\");\n        Order order = orders.placeOrder(\"late-buyer\");\n        order.onStatusChange(event -> System.out.println(\"  [push] \" + event));\n        orders.startPacking(order);\n        orders.finishPacking(order);\n        orders.dispatch(order);\n        System.out.println(\"  rider assigned: \" + order.rider().id() + \" (nearest to the store)\");\n        orders.deliver(order);\n        System.out.println(\"  final status: \" + order.status() + \", rider free again: \" + order.rider().isAvailable());\n\n        // 6. Concurrent rider claims ------------------------------------------------\n        System.out.println();\n        System.out.println(\"== 6. 5 packed orders, 3 riders, all dispatched at once ==\");\n        List<Order> packed = new java.util.ArrayList<>();\n        for (int i = 0; i < 5; i++) {\n            carts.createCart(\"bread-\" + i, home);\n            carts.addItem(\"bread-\" + i, \"bread\", 1);\n            Order o = orders.placeOrder(\"bread-\" + i);\n            orders.startPacking(o);\n            orders.finishPacking(o);\n            packed.add(o);\n        }\n        AtomicInteger dispatched = new AtomicInteger();\n        ConcurrentRunner.runAll(5, i -> {\n            if (orders.dispatch(packed.get(i))) dispatched.incrementAndGet();\n        });\n        Set<String> riderIds = ConcurrentHashMap.newKeySet();\n        packed.stream().filter(o -> o.rider() != null).forEach(o -> riderIds.add(o.rider().id()));\n        long waiting = packed.stream().filter(o -> o.status() == OrderStatus.PACKED).count();\n        System.out.println(\"Dispatched: \" + dispatched.get() + \", waiting for a rider: \" + waiting\n                + \", distinct riders used: \" + riderIds.size());\n        Order firstOut = packed.stream().filter(o -> o.status() == OrderStatus.OUT_FOR_DELIVERY).findFirst().orElseThrow();\n        orders.deliver(firstOut);\n        Order stillWaiting = packed.stream().filter(o -> o.status() == OrderStatus.PACKED).findFirst().orElseThrow();\n        System.out.println(\"After one delivery frees a rider, a waiting order dispatches: \" + orders.dispatch(stillWaiting));\n\n        // 7. Cancellation releases stock ------------------------------------------\n        System.out.println();\n        System.out.println(\"== 7. Cancellation puts stock back, exactly once ==\");\n        int before = koramangala.onHand(\"bread\");\n        carts.createCart(\"cancel-me\", home);\n        carts.addItem(\"cancel-me\", \"bread\", 2);\n        Order cancelMe = orders.placeOrder(\"cancel-me\");\n        int afterOrder = koramangala.onHand(\"bread\");\n        AtomicInteger cancelled = new AtomicInteger();\n        ConcurrentRunner.runAll(6, i -> {\n            if (orders.cancel(cancelMe)) cancelled.incrementAndGet();\n        });\n        System.out.println(\"Bread on hand: \" + before + \" -> \" + afterOrder + \" after order -> \"\n                + koramangala.onHand(\"bread\") + \" after 6 simultaneous cancel clicks\");\n        System.out.println(\"Cancel calls that took effect: \" + cancelled.get());\n        System.out.println(\"Cancel an order already out for delivery: \" + orders.cancel(\n                packed.stream().filter(o -> o.status() == OrderStatus.OUT_FOR_DELIVERY).findFirst().orElseThrow()));\n    }\n}",
